create or replace function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$ begin if value is not true then raise exception 'ASSERTION_FAILED:%',label; end if; end $$;
create or replace function pg_temp.public_execute_granted(signature regprocedure) returns boolean language sql stable as $$ select exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('